import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String s = reader.readLine();
        if (s == null || s.isEmpty()) {
            return;
        }

        int[][] count = new int[4][14];
        boolean[] hasDuplicate = new boolean[4];

        for (int i = 0; i < s.length(); i += 3) {
            int val = Integer.parseInt(s.substring(i, i + 2));
            char suit = s.charAt(i + 2);
            int suitIdx = getSuitIndex(suit);

            if (count[suitIdx][val] > 0) {
                hasDuplicate[suitIdx] = true;
            }
            count[suitIdx][val]++;
        }

        for (int i = 0; i < 4; i++) {
            if (hasDuplicate[i]) {
                System.out.println("erro");
            } else {
                int distinctCount = 0;
                for (int v = 1; v <= 13; v++) {
                    if (count[i][v] > 0) {
                        distinctCount++;
                    }
                }
                System.out.println(13 - distinctCount);
            }
        }
    }

    private static int getSuitIndex(char suit) {
        switch (suit) {
            case 'C': return 0;
            case 'E': return 1;
            case 'U': return 2;
            case 'P': return 3;
            default: return -1;
        }
    }
}
